// گرفتن خروجی تحلیل از AI Agent
const aiAnalysis = $input.first().json.output || '';

// دریافت اطلاعات قیمت‌ها از نود HTTP Request (باید به این نود متصل باشد یا از طریق itemlinking دسترسی داشته باشد)
// فرض بر این است که داده‌های خام قیمت در جریان کار موجود است
const items = $('HTTP Request').first().json;

const coins = [
  ['bitcoin',      'بیت‌کوین',      'BTC'],
  ['ethereum',     'اتریوم',        'ETH'],
  ['tether',       'تتر',           'USDT'],
  ['binancecoin',  'بایننس‌کوین',   'BNB'],
  ['solana',       'سولانا',        'SOL'],
  ['ripple',       'ریپل',          'XRP'],
  ['cardano',      'کاردانو',       'ADA'],
  ['dogecoin',     'دوج‌کوین',      'DOGE'],
  ['avalanche-2',  'آوالانچ',       'AVAX'],
  ['tron',         'ترون',          'TRX'],
];

const arrow = (change) => (change >= 0 ? '🟢▲' : '🔴▼');
const fmt = (num) => {
  if (num >= 1) {
    return num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  return num.toLocaleString('en-US', { minimumFractionDigits: 4, maximumFractionDigits: 6 });
};

let priceLines = '';
for (const [id, faName, symbol] of coins) {
  const item = items[id];
  if (!item) continue;
  const price = fmt(item.usd);
  const change = item.usd_24h_change ?? 0;
  priceLines += `🪙 <b>${faName} (${symbol})</b>\n💵 $${price}   ${arrow(change)} ${change.toFixed(2)}%\n\n`;
}

// تاریخ و ساعت به وقت تهران
const now = new Date().toLocaleString('fa-IR', {
  timeZone: 'Asia/Tehran',
  dateStyle: 'short',
  timeStyle: 'short',
});

// ترکیب نهایی پیام
const message = `📊 <b>گزارش بازار رمزارزها</b>
⏰ ${now}

${priceLines}-----------------------------
🤖 <b>تحلیل هوش مصنوعی و پیش‌بینی روز:</b>
${aiAnalysis}

`;

return [{ json: { message } }];

const coins = [
  ['bitcoin',      'بیت‌کوین',      'BTC'],
  ['ethereum',     'اتریوم',        'ETH'],
  ['tether',       'تتر',           'USDT'],
  ['binancecoin',  'بایننس‌کوین',   'BNB'],
  ['solana',       'سولانا',        'SOL'],
  ['ripple',       'ریپل',          'XRP'],
  ['cardano',      'کاردانو',       'ADA'],
  ['dogecoin',     'دوج‌کوین',      'DOGE'],
  ['avalanche-2',  'آوالانچ',       'AVAX'],
  ['tron',         'ترون',          'TRX'],
];

const data = $input.first().json;

let coinListText = '';
for (const [id, faName, symbol] of coins) {
  const item = data[id];
  if (!item) continue;
  coinListText += `- ${faName} (${symbol}): قیمت = $${item.usd}, تغییرات 24 ساعته = ${item.usd_24h_change.toFixed(2)}%\n`;
}

// این متن به عنوان ورودی داده می شود به AI Agent
return [{ json: { coinListText } }];
